pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 t, address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 0, 100 ether);
        uint256 now0 = block.timestamp;
        t = bound(t, now0 > 1 ? now0 - 1 : 0, now0 + 365 days); // allow past times
        vm.deal(actor, amount);
        vm.warp(now0);
        vm.prank(actor);
        c.Put{value: amount}(t);
        // General rule: after any Put(t), stored unlockTime >= current block timestamp.
        assertTrue(c.Acc(actor).unlockTime >= block.timestamp);
    }
}

