import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 ts, uint256 t, address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        uint256 t0 = bound(ts, 1, 365 days);
        uint256 amt = bound(amount, 0, 100 ether);
        uint256 tU = bound(t, 0, 365 days);
        vm.warp(t0);
        vm.deal(actor, amt);
        vm.prank(actor);
        c.Put{value: amt}(tU);
        (uint256 unlockTime,) = c.Acc(actor);
        assertTrue(unlockTime >= t0 && unlockTime >= tU && unlockTime != 0);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    receive() external payable {}
    function test(uint dep, uint amt) public {
        require(dep >= 2 ether);
        require(amt >= 1 ether && amt <= dep);
        require(address(this).balance >= dep);
        c.Put{value: dep}(0);
        c.Collect(amt);
        (, uint bal) = c.Acc(address(this));
        assert(bal == dep - amt);
    }
}
